package com.rustybank.legacy;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class InterestCalculator {

    public long monthlyInterest(long balanceInCents, long annualRatePercent) {
        BigDecimal balance = BigDecimal.valueOf(balanceInCents);
        BigDecimal rate = BigDecimal.valueOf(annualRatePercent);
        BigDecimal result = balance.multiply(rate)
                                   .divide(BigDecimal.valueOf(1200), 0, RoundingMode.HALF_UP);
        return result.longValue();
    }
}
