package com.rustybank.legacy;

import com.rustybank.TellerTerminal;
import java.util.ArrayList;
import java.util.List;

public class LegacyTellerTerminal implements TellerTerminal {
    private final AccountStore store;
    private final InterestCalculator interestCalculator = new InterestCalculator();

    public LegacyTellerTerminal(AccountStore store) {
        this.store = store;
    }

    public void openAccount(String accountId) {
        store.add(accountId);
    }

    public void deposit(String accountId, String amount) {
        Account a = store.find(accountId);
        a.setBalanceInCents(a.getBalanceInCents() + MoneyUtil.parseCents(amount));
    }

    public void withdraw(String accountId, String amount) {
        Account a = store.find(accountId);
        long cents = MoneyUtil.parseCents(amount);
        if (cents > a.getBalanceInCents()) throw new IllegalStateException("INSUFFICIENT FUNDS");
        a.setBalanceInCents(a.getBalanceInCents() - cents);
    }

    public String balance(String accountId) {
        return MoneyUtil.format(store.find(accountId).getBalanceInCents());
    }

    public String postMonthlyInterest(String accountId, String annualRatePercent) {
        Account a = store.find(accountId);
        long rate = Long.parseLong(annualRatePercent);
        long interest = interestCalculator.monthlyInterest(a.getBalanceInCents(), rate);
        a.setBalanceInCents(a.getBalanceInCents() + interest);
        return MoneyUtil.format(interest);
    }

    public List<String> splitPayment(String fromAccountId, String amount, List<String> payeeIds) {
        Account from = store.find(fromAccountId);
        if (payeeIds == null || payeeIds.isEmpty()) throw new IllegalArgumentException("NO PAYEES");
        long totalCents = MoneyUtil.parseCents(amount);
        if (totalCents > from.getBalanceInCents()) throw new IllegalStateException("INSUFFICIENT FUNDS");

        int n = payeeIds.size();
        long base = totalCents / n;
        int remainder = (int) (totalCents % n);

        from.setBalanceInCents(from.getBalanceInCents() - totalCents);
        List<String> shares = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            long share = base + (i < remainder ? 1 : 0);
            Account p = store.find(payeeIds.get(i));
            p.setBalanceInCents(p.getBalanceInCents() + share);
            shares.add(MoneyUtil.format(share));
        }
        return shares;
    }

    public String totalHoldings() {
        long sum = 0;
        for (Account a : store.all()) sum += a.getBalanceInCents();
        return MoneyUtil.format(sum);
    }
}
